from dataclasses import dataclass
from .errors import AccessDenied

@dataclass(frozen=True)
class Grant:
    subject: str
    operation: str
    selected: tuple[str, ...]

PREFIXES = {"reader": ("public/",), "owner": ("public/", "private/")}

def require(identity, name):
    if "read" not in identity.scopes:
        raise AccessDenied("read scope required")
    if not any(name.startswith(prefix) for prefix in PREFIXES.get(identity.role, ())):
        raise AccessDenied("record grant required")

def issue(identity, names):
    for name in names:
        require(identity, name)
    return Grant(identity.subject, "read", names)

from copy import deepcopy
from .seed import RECORDS
from .errors import NotFound

class Store:
    def __init__(self):
        self.records = deepcopy(RECORDS)

    def fetch(self, key):
        if key not in self.records:
            raise NotFound("record")
        return deepcopy(self.records[key])

    def fetch_many(self, keys):
        return [{"key": key, "record": self.fetch(key)} for key in keys]

    def metadata(self, key):
        record = self.fetch(key)
        return {"key": key, "title": record["title"]}

from collections import deque
from dataclasses import dataclass

@dataclass(frozen=True)
class Event:
    subject: str
    action: str
    count: int
    request_id: str

class Audit:
    def __init__(self, capacity=128):
        self.events = deque(maxlen=capacity)

    def record(self, request, action, count):
        self.events.append(Event(request.identity.subject, action, count, request.request_id))

    def snapshot(self):
        return tuple(self.events)

from dataclasses import dataclass
from .errors import AccessDenied

@dataclass(frozen=True)
class Identity:
    subject: str
    tenant: str
    role: str
    scopes: frozenset[str]
    enabled: bool = True

SESSIONS = {
    "demo-reader": Identity("ava", "north", "reader", frozenset({"read", "export"})),
    "demo-owner": Identity("noah", "north", "owner", frozenset({"read", "export", "purge"})),
    "demo-paused": Identity("ivy", "north", "owner", frozenset({"read", "export"}), False),
}

def authenticate(token):
    identity = SESSIONS.get(token)
    if identity is None or not identity.enabled:
        raise AccessDenied("inactive session")
    return identity

from dataclasses import dataclass
from .errors import InvalidRequest
from .identity import authenticate

@dataclass(frozen=True)
class Request:
    identity: object
    arguments: dict
    request_id: str

class Registry:
    def __init__(self):
        self.handlers = {}

    def register(self, name, handler):
        if name in self.handlers:
            raise ValueError("duplicate tool")
        self.handlers[name] = handler

    def invoke(self, name, token, arguments, request_id="local"):
        if not isinstance(arguments, dict):
            raise InvalidRequest("arguments must be an object")
        if name not in self.handlers:
            raise InvalidRequest("unknown tool")
        request = Request(authenticate(token), arguments, request_id)
        return self.handlers[name](request)

    def describe(self):
        return tuple(sorted(self.handlers))
